SELECT	listagg (substr(p."Registraèní èíslo projektu",-5,5), '; ') "Zkrácené èíslo projektu",
	count(p.id),
	p."IÈ",
	p.zadatel,
	listagg(p.kodwfstav , '; ') WITHIN GROUP (ORDER BY p.kodwfstav ) "Stavy projektù",
	listagg(DISTINCT v."Èíslo výzvy", '; ') "Výzvy",
	celoplosne.pocet "V celoplo¹ných výzvách",
 	celoplosne."Stavy projektù" "V celople¹ných výzvách"
	
FROM isum.v_bi_UmzProjekt p 
INNER JOIN isum.v_bi_UmzVyzva v ON v.id=p.id_vyzva 
LEFT JOIN
(SELECT	count(p.id) pocet,
 	p."IÈ",
 	listagg(p.kodwfstav , '; ') WITHIN GROUP (ORDER BY p.kodwfstav ) "Stavy projektù"

FROM isum.v_bi_UmzProjekt p

